function renderTeoria(el){
  el.innerHTML = `${cabecera('teoria',T('Todo lo que conviene tener claro para formular bien. Cada sección indica el bloque donde se aplica.','Everything worth knowing to formulate well. Each section shows the block where it applies.'))}
  <section class="teoria"><div class="th"><div><h2>${T('Marco teórico de la formulación de raciones para bovinos de carne','Theoretical framework of beef cattle ration formulation')}</h2><p>${T('Despliega la sección que necesites.','Open the section you need.')}</p></div></div>
  ${TEORIA.map((t,i)=>`<details ${i===0?'open':''}><summary>${i+1} · ${esc(tx(t.t))} ${t.b?`<span class="badge">${T('Bloque','Block')} ${t.b}</span>`:''}</summary><div class="tb">${tx(t.h)}</div></details>`).join('')}</section>
  <div class="card small"><h3>${T('Referencias','References')}</h3><ul>${REFERENCIAS.slice().sort((a,b)=>a.localeCompare(b,'es')).map(r=>`<li>${r}</li>`).join('')}</ul></div>
  ${siguiente('teoria')}`;
}

/* =====================================================================
   9. NAVEGACIÓN, IDIOMA Y TEMA / NAVIGATION, LANGUAGE AND THEME
   ===================================================================== */
function renderNav(){
  $('#nav').innerHTML = BLOQUES.map(b=>`<button class="${S.bloque===b.id?'act':''} ${S.visitados[b.id]&&S.bloque!==b.id&&/^\d+$/.test(b.n)?'done':''}" data-ir="${b.id}"><span class="n">${b.n}</span>${esc(tx(b.corto))}</button>`).join('');
  const a = $('#nav .act'); if(a && a.scrollIntoView) a.scrollIntoView({block:'nearest',inline:'center'});
  const hechos = BLOQUES.filter(b=>/^\d+$/.test(b.n) && (S.visitados[b.id]||S.bloque===b.id)).length;
  $('#progTxt').textContent = T(`Avance: ${hechos} de ${NUMERADOS} bloques`,`Progress: ${hechos} of ${NUMERADOS} blocks`);
  $('#progFill').style.width = (100*hechos/NUMERADOS)+'%';
}
function actualizarPill(){
  const t = $('#pillTxt'); if(t) t.textContent = `${tx(CATEGORIAS[S.cat].n)} · ${tx(REGIONES[S.region].n)}` + (S.resultado&&S.resultado.ok?` · ${money(S.resultado.costoKgTCO*1000,0)}/t`:'');
}
function renderAyuda(){
  $('#dlgAyuda').innerHTML = `<div class="dh"><h2>${T('Cómo usar RatioBos','How to use RatioBos')}</h2><button class="ibtn round" onclick="this.closest('dialog').close()" aria-label="×">✕</button></div>
  <div class="db"><ol>
    <li>${T('<b>Avanza en orden</b> por los bloques: animal, región, requerimientos, manejo, ingredientes y precios.','<b>Move in order</b> through the blocks: animal, region, requirements, management, ingredients and prices.')}</li>
    <li>${T('En <b>Formulación</b> presiona <i>Formular</i>: se calcula la ración de mínimo costo y la ganancia que permite.','In <b>Formulation</b> press <i>Formulate</i>: the least-cost ration and the gain it allows are computed.')}</li>
    <li>${T('En <b>Programa</b> simulas toda la engorda o el ciclo de la vaca; en <b>Tablero</b> ves todo en gráficas; en <b>Sostenibilidad</b>, la huella ambiental.','In <b>Program</b> you simulate the whole feeding period or cow cycle; <b>Dashboard</b> shows everything in charts; <b>Sustainability</b> shows the environmental footprint.')}</li>
    <li>${T('El botón <b>Productor / Científico</b> cambia la vista; <b>ES / EN</b> cambia el idioma sin perder tus datos.','The <b>Producer / Scientist</b> button switches view; <b>ES / EN</b> switches language without losing your data.')}</li>
    <li>${T('Tu trabajo se <b>guarda solo</b> en este navegador. Para llevarlo a otra computadora usa <i>Informe → Guardar proyecto</i>.','Your work is <b>saved automatically</b> in this browser. To move it to another computer use <i>Report → Save project</i>.')}</li>
  </ol><p class="small muted">${T('Los valores precargados son de referencia. Revisa la ración con tu médico veterinario zootecnista o nutriólogo y analiza tus forrajes.','Preloaded values are references. Review the ration with your veterinarian or nutritionist and analyze your forages.')}</p></div>`;
}
function render(){
  document.documentElement.lang = LANG;
  $$('.langsw button[data-lang]').forEach(b=>b.classList.toggle('on', b.dataset.lang===LANG));
  document.documentElement.setAttribute('data-modo', MODO);
  $$('.modesw button').forEach(b=>{ const on=b.dataset.vista===MODO; b.classList.toggle('on',on); b.setAttribute('aria-pressed', on); });
  $('#lblProd').textContent = T('Productor','Producer'); $('#lblCien').textContent = T('Científico','Scientist');
  $('#modesw').title = T('Vista para productor o para científico','Producer or scientist view');
  $('#brandSub').textContent = T('· la razón al servicio del ganado','· reason in the service of cattle');
  const b = B(S.bloque) || BLOQUES[0];
  b.render()($('#main'));
  $('#pie').innerHTML = `<svg style="width:26px;height:26px;vertical-align:middle;margin-right:6px"><use href="#i-logo" width="100%" height="100%"/></svg><b>RatioBos</b> ${CONFIG.version} · ${T('Formulación de raciones para bovinos productores de carne','Beef cattle ration formulation')} · ${esc(CONFIG.autores)} · ${CONFIG.anio}<br><span class="tiny">${T('Herramienta de apoyo: los resultados deben ser revisados por un profesional en nutrición animal.','Decision-support tool: results should be reviewed by a qualified animal nutritionist.')} · MIT</span>`;
  renderNav(); actualizarPill(); renderAyuda();
}
function irA(id){ S.visitados[S.bloque]=true; S.bloque=id; guardar(); render(); window.scrollTo({top:0,behavior:'smooth'}); }
document.addEventListener('click',e=>{ const t=e.target.closest('[data-ir]'); if(t){ irA(t.dataset.ir); } });
function ponerModo(m){ MODO = m==='cien'?'cien':'prod'; try{ localStorage.setItem('ratiobos_modo',MODO); }catch(e){} render();
  toast(MODO==='cien'?T('Vista científica: modelo, iteraciones, validación y referencias','Scientist view: model, iterations, validation and references'):T('Vista productor: lo esencial, en lenguaje sencillo','Producer view: the essentials, in plain language')); }
document.addEventListener('click',e=>{ const t=e.target.closest('[data-vista]'); if(t){ ponerModo(t.dataset.vista); } });
$$('.langsw button[data-lang]').forEach(b=>b.addEventListener('click',()=>{ LANG=b.dataset.lang; try{ localStorage.setItem('ratiobos_lang',LANG); }catch(e){} render(); toast(LANG==='en'?'English':'Español'); }));
function aplicarTema(t){ if(t) document.documentElement.setAttribute('data-theme',t); else document.documentElement.removeAttribute('data-theme');
  const dark = t ? t==='dark' : matchMedia('(prefers-color-scheme: dark)').matches; $('#btnTema').textContent = dark?'☾':'☀'; }
$('#btnTema').addEventListener('click',()=>{ const cur = document.documentElement.getAttribute('data-theme') || (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
  const nt = cur==='dark'?'light':'dark'; aplicarTema(nt); try{ localStorage.setItem('ratiobos_tema',nt); }catch(e){} });
$('#btnAyuda').addEventListener('click',()=>{ const d=$('#dlgAyuda'); if(d.showModal) d.showModal(); });
