/* símbolo del mapa para la cabecera del Bloque 2, construido con los contornos */
(function(){ const sp = document.querySelector('svg defs'); if(!sp) return; const ns='http://www.w3.org/2000/svg';
  const sym = document.createElementNS(ns,'symbol'); sym.setAttribute('id','i-mapa'); sym.setAttribute('viewBox',`0 0 ${MAPA_MX.w} ${MAPA_MX.h}`);
  sym.innerHTML = Object.entries(MAPA_MX.edo).map(([k,d])=>`<path d="${d}" fill="${(REGIONES[REGION_DE_EDO[k]]||{color:'#9cbf5a'}).color}" stroke="#fffaf0" stroke-width="3"/>`).join('');
  sp.parentNode.appendChild(sym); })();

